--

CREATE FUNCTION public.charge_payments_guard_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Charge payment allocations are immutable';
    END IF;

    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'Charge payment allocations are immutable';
    END IF;

    RETURN NEW;
END;
$$;


