CREATE FUNCTION public.cl_validate_group_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ DECLARE v_assigned_group uuid; v_creator_group uuid; v_plan_group uuid; BEGIN IF NEW.assigned_to IS NOT NULL THEN SELECT m.group_id INTO v_assigned_group FROM public.members m WHERE m.id=NEW.assigned_to; IF v_assigned_group IS NULL OR v_assigned_group<>NEW.group_id THEN RAISE EXCEPTION 'Activity assignee does not belong to this group'; END IF; END IF; IF NEW.created_by IS NOT NULL THEN SELECT m.group_id INTO v_creator_group FROM public.members m WHERE m.id=NEW.created_by; IF v_creator_group IS NULL OR v_creator_group<>NEW.group_id THEN RAISE EXCEPTION 'Activity creator does not belong to this group'; END IF; END IF; IF NEW.plan_id IS NOT NULL THEN SELECT p.group_id INTO v_plan_group FROM public.group_plans p WHERE p.id=NEW.plan_id; IF v_plan_group IS NULL OR v_plan_group<>NEW.group_id THEN RAISE EXCEPTION 'Activity plan does not belong to this group'; END IF; END IF; RETURN NEW; END; $$;


