CREATE FUNCTION public.cl_validate_group_milestone() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ DECLARE v_creator_group uuid; v_plan_group uuid; v_document_group uuid; BEGIN IF NEW.created_by IS NOT NULL THEN SELECT m.group_id INTO v_creator_group FROM public.members m WHERE m.id=NEW.created_by; IF v_creator_group IS NULL OR v_creator_group<>NEW.group_id THEN RAISE EXCEPTION 'Milestone creator does not belong to this group'; END IF; END IF; IF NEW.plan_id IS NOT NULL THEN SELECT p.group_id INTO v_plan_group FROM public.group_plans p WHERE p.id=NEW.plan_id; IF v_plan_group IS NULL OR v_plan_group<>NEW.group_id THEN RAISE EXCEPTION 'Milestone plan does not belong to this group'; END IF; END IF; IF NEW.document_id IS NOT NULL THEN SELECT d.group_id INTO v_document_group FROM public.documents d WHERE d.id=NEW.document_id; IF v_document_group IS NULL OR v_document_group<>NEW.group_id THEN RAISE EXCEPTION 'Milestone document does not belong to this group'; END IF; END IF; RETURN NEW; END; $$;


