-- Name: COLUMN groups.category; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.groups.category IS 'Group category/type displayed by CHAMA LIVE Group Management.';


--
-- Name: get_my_group(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_my_group() RETURNS public.groups
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT g.*
  FROM public.groups g
  JOIN public.members m ON m.group_id = g.id
  WHERE (m.user_id = auth.uid() OR m.auth_user_id = auth.uid())
    AND lower(coalesce(m.status, 'active')) = 'active'
  ORDER BY m.created_at
  LIMIT 1;
$$;


ALTER FUNCTION public.get_my_group() OWNER TO postgres;

--
-- Name: get_my_groups(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_my_groups() RETURNS TABLE(group_id uuid, group_name text, role text, category text, monthly_contribution numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select g.id, g.name, m.role, g.category, g.monthly_contribution
  from public.members m
  join public.groups g on g.id = m.group_id
  where (m.user_id = auth.uid() or m.auth_user_id = auth.uid())
    and lower(coalesce(m.status,'active')) = 'active'
    and lower(coalesce(m.onboarding_status,'active')) = 'active'
  order by m.created_at;
$$;


ALTER FUNCTION public.get_my_groups() OWNER TO postgres;

