--
-- Name: renewal_attempts; Type: TABLE; Schema: private; Owner: postgres
--

CREATE TABLE private.renewal_attempts (
    attempt_id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_id uuid NOT NULL,
    subscription_id uuid NOT NULL,
    attempted_at timestamp with time zone DEFAULT now() NOT NULL,
    execution_source text NOT NULL,
    result text NOT NULL,
    cycle_before integer,
    cycle_after integer,
    invoice_id uuid,
    idempotency_key text NOT NULL,
    error_code text,
    error_message text,
    CONSTRAINT renewal_attempts_cycle_after_ck CHECK (((cycle_after IS NULL) OR (cycle_after >= 1))),
    CONSTRAINT renewal_attempts_cycle_before_ck CHECK (((cycle_before IS NULL) OR (cycle_before >= 1))),
    CONSTRAINT renewal_attempts_execution_source_ck CHECK ((execution_source = ANY (ARRAY['human'::text, 'scheduler'::text]))),
    CONSTRAINT renewal_attempts_result_ck CHECK ((result = ANY (ARRAY['renewed'::text, 'not_due'::text, 'already_renewed'::text, 'anomalous'::text, 'failed'::text]))),
    CONSTRAINT renewal_attempts_result_invariants_ck CHECK ((((result = 'renewed'::text) AND (cycle_before IS NOT NULL) AND (cycle_after = (cycle_before + 1)) AND (invoice_id IS NOT NULL)) OR ((result = 'not_due'::text) AND (cycle_before IS NOT NULL) AND (cycle_after IS NULL) AND (invoice_id IS NULL)) OR ((result = 'already_renewed'::text) AND (cycle_before IS NOT NULL) AND (cycle_after IS NOT NULL) AND (cycle_after > cycle_before) AND (invoice_id IS NOT NULL)) OR ((result = 'anomalous'::text) AND (cycle_after IS NULL) AND (invoice_id IS NULL)) OR ((result = 'failed'::text) AND (cycle_before IS NOT NULL) AND (cycle_after IS NULL) AND (invoice_id IS NULL))))
);


ALTER TABLE private.renewal_attempts OWNER TO postgres;

