    error_message text,
    CONSTRAINT renewal_runs_execution_source_ck CHECK ((execution_source = ANY (ARRAY['human'::text, 'scheduler'::text]))),
    CONSTRAINT renewal_runs_status_ck CHECK ((status = ANY (ARRAY['running'::text, 'completed'::text, 'failed'::text]))),
    CONSTRAINT renewal_runs_status_completion_ck CHECK ((((status = 'running'::text) AND (completed_at IS NULL)) OR ((status = ANY (ARRAY['completed'::text, 'failed'::text])) AND (completed_at IS NOT NULL))))
);


ALTER TABLE private.renewal_runs OWNER TO postgres;

