    subscription_id uuid NOT NULL,
    group_id uuid NOT NULL,
    member_id uuid NOT NULL,
    billable_from_cycle_id uuid NOT NULL,
    billable_until_cycle_id uuid,
    activated_at timestamp with time zone NOT NULL,
    deactivated_at timestamp with time zone,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT subscription_member_billing_dates_ck CHECK (((deactivated_at IS NULL) OR (deactivated_at >= activated_at))),
    CONSTRAINT subscription_member_billing_status_ck CHECK ((status = ANY (ARRAY['active'::text, 'ended'::text])))
);


ALTER TABLE public.subscription_member_billing OWNER TO postgres;

--
-- Name: subscription_payment_allocations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.subscription_payment_allocations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    payment_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    allocation_type text NOT NULL,
    credit_id uuid,
    amount numeric NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    reversed_at timestamp with time zone,
    CONSTRAINT subscription_payment_allocations_allocation_type_check CHECK ((allocation_type = ANY (ARRAY['direct'::text, 'credit'::text]))),
    CONSTRAINT subscription_payment_allocations_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT subscription_payment_allocations_credit_ck CHECK ((((allocation_type = 'direct'::text) AND (credit_id IS NULL)) OR ((allocation_type = 'credit'::text) AND (credit_id IS NOT NULL)))),
    CONSTRAINT subscription_payment_allocations_reversed_at_ck CHECK ((((status = 'reversed'::text) AND (reversed_at IS NOT NULL)) OR ((status <> 'reversed'::text) AND (reversed_at IS NULL)))),
    CONSTRAINT subscription_payment_allocations_status_check CHECK ((status = ANY (ARRAY['active'::text, 'reversed'::text])))
);


ALTER TABLE public.subscription_payment_allocations OWNER TO postgres;

--
-- Name: subscription_payments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.subscription_payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    invoice_id uuid NOT NULL,
    group_id uuid NOT NULL,
    amount numeric(12,2) NOT NULL,
    payment_method text NOT NULL,
    provider text,
    provider_reference text,
    status text DEFAULT 'pending'::text NOT NULL,
    paid_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT subscription_payments_amount_ck CHECK ((amount > (0)::numeric)),
    CONSTRAINT subscription_payments_method_ck CHECK ((payment_method = ANY (ARRAY['mpesa'::text, 'bank'::text, 'cash'::text, 'other'::text]))),
    CONSTRAINT subscription_payments_status_ck CHECK ((status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'failed'::text, 'reversed'::text, 'cancelled'::text])))
);


ALTER TABLE public.subscription_payments OWNER TO postgres;

--
-- Name: subscription_pricing_tiers; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.subscription_pricing_tiers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tier_code text NOT NULL,
    min_members integer NOT NULL,
    max_members integer,
    standard_group_amount numeric(12,2) NOT NULL,
    standard_member_login_amount numeric(12,2) NOT NULL,
    currency text DEFAULT 'KES'::text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT subscription_pricing_tiers_amount_ck CHECK (((standard_group_amount >= (0)::numeric) AND (standard_member_login_amount >= (0)::numeric))),
    CONSTRAINT subscription_pricing_tiers_currency_ck CHECK ((currency = 'KES'::text)),
    CONSTRAINT subscription_pricing_tiers_max_ck CHECK (((max_members IS NULL) OR (max_members >= min_members))),
    CONSTRAINT subscription_pricing_tiers_min_ck CHECK ((min_members >= 1))
);


ALTER TABLE public.subscription_pricing_tiers OWNER TO postgres;

