--
-- Name: subscription_credit_balances _RETURN; Type: RULE; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW public.subscription_credit_balances WITH (security_invoker='true') AS
 SELECT c.id AS credit_id,
    c.source_payment_id,
    c.original_amount,
    c.status,
    c.created_at,
    c.reversed_at,
        CASE
            WHEN (c.status = 'reversed'::text) THEN (0)::numeric
            ELSE GREATEST((c.original_amount - COALESCE(sum(
            CASE
                WHEN (a.status = 'active'::text) THEN a.amount
                ELSE (0)::numeric
            END), (0)::numeric)), (0)::numeric)
        END AS remaining_amount
   FROM (public.subscription_credits c
     LEFT JOIN public.subscription_payment_allocations a ON ((a.credit_id = c.id)))
  GROUP BY c.id;


