--
-- Name: group_applications Applicants can view their own application; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Applicants can view their own application" ON public.group_applications FOR SELECT TO authenticated USING ((( SELECT auth.uid() AS uid) = auth_user_id));


--
-- Name: contribution_goals admin or secretary creates goals; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "admin or secretary creates goals" ON public.contribution_goals FOR INSERT WITH CHECK ((public.my_role(group_id) = ANY (ARRAY['admin'::text, 'secretary'::text])));


--
-- Name: contribution_goals admin or secretary updates goals; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "admin or secretary updates goals" ON public.contribution_goals FOR UPDATE USING ((public.my_role(group_id) = ANY (ARRAY['admin'::text, 'secretary'::text])));


