--
-- Name: contribution_initiative_credit_consumptions contribution_initiative_credit_consumptions_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY contribution_initiative_credit_consumptions_select ON public.contribution_initiative_credit_consumptions FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM (((public.contribution_initiative_credits c
     JOIN public.contribution_initiative_allocations a ON ((a.id = contribution_initiative_credit_consumptions.allocation_id)))
     JOIN public.contribution_initiative_obligations o ON ((o.id = a.initiative_obligation_id)))
     JOIN public.contribution_initiatives i ON ((i.id = o.initiative_id)))
  WHERE ((c.id = contribution_initiative_credit_consumptions.credit_id) AND public.cl_user_in_group(i.group_id)))));


